import { useEffect, useState } from "react";

export default function Forecast() {
  const [data, setData] = useState(null);

  useEffect(() => {
    fetch("http://127.0.0.1:8000/api/forecast-items/")
      .then(r => r.json())
      .then(setData)
      .catch(() => setData({}));
  }, []);

  return (
    <div className="forecast-page">
      <h2>🔮 ML Forecast — Future Quantity</h2>

      <div className="forecast-grid">

        {data === null && (
          <div className="forecast-card">Loading...</div>
        )}

        {data && Object.keys(data).length === 0 && (
          <div className="forecast-card">No forecast data</div>
        )}

        {data && Object.entries(data).map(([item, qty]) => (
          <div className="forecast-card" key={item}>
            <h3>{item}</h3>
            <p className="forecast-qty">{qty}</p>
            <span>Predicted Quantity</span>
          </div>
        ))}

      </div>
    </div>
  );
}
